import { mkdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type Database from 'better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import type { Db } from './database.ts';

/** Migrations generated by drizzle-kit; the folder sits next to src/ and dist/ alike. */
export const MIGRATIONS_DIR = fileURLToPath(new URL('../../drizzle', import.meta.url));

interface JournalEntry {
  tag: string;
  when: number;
}

function journal(migrationsDir: string): JournalEntry[] {
  const raw = JSON.parse(readFileSync(join(migrationsDir, 'meta', '_journal.json'), 'utf8')) as {
    entries: JournalEntry[];
  };
  return raw.entries;
}

/** drizzle applies every journal entry newer than the newest recorded migration. */
function lastAppliedAt(sqlite: Database.Database): number | null {
  const table = sqlite
    .prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = '__drizzle_migrations'")
    .get();
  if (!table) return null;
  const row = sqlite.prepare('SELECT max(created_at) AS at FROM __drizzle_migrations').get() as {
    at: number | null;
  };
  return row.at;
}

export interface MigrationResult {
  applied: string[];
  backupFile: string | null;
}

/**
 * Brings the schema up to date. A database that already holds data is copied with `VACUUM INTO`
 * before the first pending migration runs (ADR 0004), so a failed upgrade can be rolled back by hand.
 */
export function migrateDatabase(
  handle: { sqlite: Database.Database; db: Db },
  options: { migrationsDir?: string; backupDir: string | null },
): MigrationResult {
  const migrationsDir = options.migrationsDir ?? MIGRATIONS_DIR;
  const appliedAt = lastAppliedAt(handle.sqlite);
  const pending = journal(migrationsDir).filter((entry) => appliedAt === null || entry.when > appliedAt);
  if (pending.length === 0) return { applied: [], backupFile: null };

  let backupFile: string | null = null;
  if (appliedAt !== null && options.backupDir) {
    mkdirSync(options.backupDir, { recursive: true });
    backupFile = join(options.backupDir, `pre-migration-${pending[0]?.tag}-${Date.now()}.db`);
    handle.sqlite.prepare('VACUUM INTO ?').run(backupFile);
  }
  migrate(handle.db, { migrationsFolder: migrationsDir });
  return { applied: pending.map((entry) => entry.tag), backupFile };
}
